const fs = require("node:fs");
const path = require("node:path");
const catalog = require("../src/desktop/AchievementCatalog.json");

async function generateAchievements(root = path.resolve(__dirname, "..")) {
  const source =
    "// Generated by scripts/generate-achievements.js.\nmodule.exports = " +
    JSON.stringify(catalog, null, 2) +
    ";\n";
  fs.writeFileSync(
    path.join(root, "electron/achievement-catalog.cjs"),
    await require("prettier").format(source, { parser: "babel" }),
  );
  const { STATS } = require("../electron/steam-achievements.cjs");
  fs.writeFileSync(
    path.join(root, "steamworks/achievement-stats.csv"),
    "apiName,type,default,min,max,incrementOnly,setBy\n" +
      STATS.map(({ name }) => `${name},INT,0,0,1,true,Client`).join("\n") +
      "\n",
  );
}
if (require.main === module) void generateAchievements();
module.exports = { generateAchievements };
